-- Verify: shipment CC590728 has TED=118 min, total_transit_min=300
-- TIRP = (300 - 118) / 300 * 100 = 60.67%
SELECT ROUND(CAST((300 - 118)::numeric / 300 * 100 AS numeric), 2);

SELECT COUNT(*) FROM (
    SELECT s.reckey
    FROM shipments s
    JOIN environmentalmonitoring em ON s.reckey = em.reckeylink
    CROSS JOIN LATERAL (
        SELECT s.shipment_overview->'timing_performance'->>'actual_duration_hrs' as actual_duration_hrs
    ) sp
    WHERE (em.env_metrics->'temperature'->>'excursion_duration_min')::int > 60
) sub;

SELECT COUNT(*) FROM (
    SELECT s.reckey
    FROM shipments s
    JOIN environmentalmonitoring em ON s.reckey = em.reckeylink
    CROSS JOIN LATERAL (
        SELECT s.shipment_overview->'timing_performance'->>'actual_duration_hrs' as actual_duration_hrs
    ) sp
    WHERE (em.env_metrics->'temperature'->>'excursion_duration_min')::int > 60
      AND sp.actual_duration_hrs IS NOT NULL
) sub;

